<?php require __DIR__.'/../app/bootstrap.php';admin_required();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}csrf_check();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT image FROM products WHERE id=?');$s->execute([$id]);$image=$s->fetchColumn();if($image){$path=__DIR__.'/../uploads/products/'.basename($image);if(is_file($path))unlink($path);}$s=db()->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);header('Location: '.url('admin/products.php?deleted=1'));exit;